// Üretilen dosya: tool/ozgun/uret.py. Sanat · Rönesans ve Barok sanatı ayrıntılı (zor).
const ozArt6Zor = <(String, String, List<String>, String)>[
  ('Donatello\'nun Orsanmichele için yaptığı Aziz Yorgi heykelinin kaidesindeki ejderha sahnesi, yüzeyden ancak birkaç milimetre yükselen, çizime yakın bir kabartmayla işlenmiştir. Bu tekniğin İtalyanca adı nedir?', 'Rilievo schiacciato', ['Alto rilievo', 'Tutto tondo', 'Intaglio'], 'Schiacciato (ezilmiş) kabartma, çok sığ oymayla hava perspektifi etkisi yaratır. Donatello bu tekniğin öncüsü sayılır.'),
  ('Orsanmichele\'de taş ve ahşap ustaları loncası için antik Roma giysili \'Dört Taçlı Aziz\' (Quattro Santi Coronati) heykel grubunu yapan Floransalı heykeltıraş kimdir?', 'Nanni di Banco', ['Luca della Robbia', 'Michelozzo', 'Desiderio da Settignano'], 'Nanni di Banco\'nun yaklaşık 1410-1416 arasındaki bu grubu, figürlere Roma senatörü havası vermesiyle antik heykele dönüşün erken örneklerindendir.'),
  ('Donatello\'nun Floransa Çan Kulesi için yaptığı ve kel başı yüzünden halkın \'Zuccone\' (kabak kafa) lakabını taktığı peygamber heykeli genellikle hangi peygamber olarak tanımlanır?', 'Habakkuk', ['Yeremya', 'Daniel', 'Elişa'], 'Zuccone, çan kulesinin nişleri için yapılmış ve Habakkuk olarak tanımlanır. Donatello\'nun bu heykeli çok sevdiği ve onunla konuştuğu anlatılır.'),
  ('Andrea del Verrocchio\'nun Venedik\'teki Santi Giovanni e Paolo meydanında bulunan atlı bronz heykeli hangi paralı asker komutanını gösterir?', 'Bartolomeo Colleoni', ['Erasmo da Narni', 'Francesco Sforza', 'Federico da Montefeltro'], 'Colleoni heykeli Verrocchio\'nun son büyük işidir ve ölümünden sonra Alessandro Leopardi tarafından dökülüp tamamlanmıştır. Erasmo da Narni ise Donatello\'nun Gattamelata\'sıdır.'),
  ('Bolonya\'daki San Petronio Bazilikası\'nın ana kapısını Yaratılış sahneleriyle süsleyen ve güçlü, kaslı figürleriyle genç Michelangelo\'yu etkilediği kabul edilen Sienalı heykeltıraş kimdir?', 'Jacopo della Quercia', ['Andrea Pisano da Pontedera', 'Nanni di Banco', 'Bernardo Rossellino'], 'Jacopo della Quercia 1401 yarışmasına da katılmıştı. Michelangelo\'nun Sistina tavanındaki Âdem\'in yaratılışı sahnesinde onun kabartmalarının izleri görülür.'),
  ('Floransa\'daki Santa Croce Kilisesi\'nde, hümanist şansölye ve tarihçi Leonardo Bruni\'yi göğsünde kitabıyla yatar hâlde gösteren mezar anıtını yapan heykeltıraş kimdir?', 'Bernardo Rossellino', ['Desiderio da Settignano', 'Mino da Fiesole', 'Benedetto da Maiano'], '1440\'lardaki bu mezar, klasik kemer ve pilastrlarla çevrili \'hümanist mezar\' tipinin örneği olmuştur. Desiderio da Settignano ise hemen yakınındaki Marsuppini mezarını yapmıştır.'),
  ('1438-1439 Ferrara-Floransa Konsili\'ne katılan Bizans İmparatoru VIII. İoannis Palaiologos için yaptığı madalyayla Rönesans portre madalyası geleneğini başlatan sanatçı kimdir?', 'Pisanello', ['Gentile Bellini', 'Lorenzo Ghiberti', 'Benozzo Gozzoli'], 'Pisanello\'nun bu madalyası, antik sikkeleri örnek alan profil portreli madalya türünün ilki kabul edilir. Pisanello daha sonra birçok İtalyan hükümdarı için madalya yaptı.'),
  ('Masaccio\'nun 1428\'deki ölümüyle yarım kalan Brancacci Şapeli freskleri 1480\'lerde hangi ressam tarafından tamamlanmıştır?', 'Filippino Lippi', ['Domenico Ghirlandaio', 'Benozzo Gozzoli', 'Andrea del Castagno'], 'Brancacci ailesinin Medicilerle çatışması da işi geciktirdi. Filippino Lippi, yarım yüzyılı aşkın bir aradan sonra fresk döngüsünü bitirdi.'),
  ('Floransa\'daki Sant\'Apollonia manastırının yemekhanesinde, Yudas\'ı masanın öbür yanında tek başına oturtan sert ve heykelsi bir \'Son Akşam Yemeği\' freski yapan ressam kimdir?', 'Andrea del Castagno', ['Fra Angelico', 'Masolino da Panicale', 'Paolo Uccello'], 'Castagno\'nun 1440\'lardaki bu freski, mermer kaplı bir oda içinde güçlü perspektifle kurulmuştur. Figürlerin heykel gibi sert çizimi Castagno\'nun tipik özelliğidir.'),
  ('Floransa Katedrali\'nde İngiliz paralı asker John Hawkwood\'u atının üstünde, bronz heykel izlenimi veren yeşilimsi tek renkli bir freskle gösteren ressam kimdir?', 'Paolo Uccello', ['Andrea del Castagno', 'Masaccio', 'Domenico Veneziano'], 'Kent, mermer bir atlı heykel yerine daha ucuz olan bu boyalı anıtı ısmarladı. Uccello 1436\'da tamamladığı freskte kaideyi ve atı ayrı bakış açılarıyla çizmiştir.'),
  ('Piero della Francesca\'nın genç yaşta yanında çalıştığı, \'Santa Lucia de\' Magnoli Sunağı\'ndaki açık, aydınlık renkleriyle tanınan ressam kimdir?', 'Domenico Veneziano', ['Masaccio', 'Fra Angelico', 'Paolo di Dono'], 'Belgeler 1439\'da Piero\'nun Domenico Veneziano\'yla Floransa\'da çalıştığını gösterir. Domenico\'nun gün ışığıyla dolu renk anlayışı Piero\'yu derinden etkiledi.'),
  ('Banker Palla Strozzi için 1423\'te yapılan, altın süslemeli ve kalabalık \'Müneccimlerin Tapınması\' sunağıyla Uluslararası Gotik üslubun Floransa\'daki en gösterişli örneğini veren ressam kimdir?', 'Gentile da Fabriano', ['Lorenzo Monaco da Firenze', 'Simone Martini', 'Pisanello'], 'Strozzi Sunağı bugün Uffizi\'dedir. Masaccio\'nun yalın yeniliklerinden yalnız birkaç yıl önce yapılmış olması, iki üslubun aynı kentte yan yana yaşadığını gösterir.'),
  ('Aldous Huxley\'in \'dünyanın en güzel resmi\' dediği, II. Dünya Savaşı\'nda bir İngiliz topçu subayının bu sözü hatırlayıp Sansepolcro\'yu bombalamaktan kaçınmasıyla kurtulduğu anlatılan Piero della Francesca freski hangisidir?', 'İsa\'nın Dirilişi', ['İsa\'nın Vaftizi', 'Kutsal Haç Efsanesi', 'İsa\'nın Kırbaçlanması'], 'Fresk Sansepolcro belediye binasındadır. Subay Anthony Clarke\'ın hikâyesi, eserin kentin simgesi olarak anılmasını pekiştirmiştir.'),
  ('Piero della Francesca\'nın resimde perspektifin geometrik kurallarını adım adım anlatan kitabının adı nedir?', 'De prospectiva pingendi', ['De pictura libri tres', 'De divina proportione', 'De re aedificatoria'], 'Piero kitabında cisimlerin perspektif çizimini geometrik problemler hâlinde anlatır. De pictura Alberti\'nin, De divina proportione Luca Pacioli\'nin eseridir.'),
  ('Andrea Mantegna, Venedikli ressam Jacopo Bellini\'nin kızıyla evlenerek hangi ressamın eniştesi olmuştur?', 'Giovanni Bellini', ['Vittore Carpaccio', 'Antonello da Messina', 'Cima da Conegliano'], 'Mantegna 1453\'te Nicolosia Bellini ile evlendi. Bu bağ, Mantegna\'nın keskin çizgisiyle Giovanni Bellini\'nin erken üslubu arasındaki yakınlığı açıklar.'),
  ('Mantegna\'nın Padova\'daki Eremitani Kilisesi\'nde bulunan Ovetari Şapeli freskleri büyük ölçüde nasıl yok olmuştur?', '1944\'te bir hava bombardımanında', ['1630 veba salgınında yakılarak', '1966 sel felaketinde', '18. yüzyılda kenti sarsan bir depremde'], 'Kilise II. Dünya Savaşı\'nda Müttefik bombalarıyla yıkıldı. Fresklerin yalnız küçük bir bölümü kurtarıldı; parçalar sonradan titiz bir çalışmayla yerleştirildi.'),
  ('Mantegna\'nın Gonzaga ailesi için yaptığı dokuz büyük tuvallik \'Sezar\'ın Zaferleri\' dizisi, 1620\'lerde I. Charles\'ın satın almasının ardından bugün nerede bulunmaktadır?', 'Hampton Court Sarayı\'nda', ['Paris\'teki Louvre Müzesi\'nde', 'Prado Müzesi\'nde', 'Uffizi Galerisi\'nde'], 'İngiltere Kralı I. Charles, Gonzaga koleksiyonunun büyük kısmını satın aldı. Dizi bugün İngiliz Kraliyet Koleksiyonu\'na aittir ve Hampton Court\'ta sergilenir.'),
  ('Giovanni Bellini\'nin Ferrara Dükü Alfonso d\'Este için yaptığı \'Tanrıların Şöleni\' tablosunun arka plan manzarasını, Bellini\'nin ölümünden sonra yeniden boyayan ressam kimdir?', 'Tiziano', ['Giorgione', 'Tintoretto', 'Lorenzo Lotto'], 'Tablo, Alfonso\'nun Camerino d\'Alabastro odası için yapılmıştı. Tiziano aynı oda için yaptığı kendi bakkhanaleleriyle uyum sağlamak üzere manzarayı değiştirdi; eser bugün Washington\'dadır.'),
  ('Botticelli\'nin, üzerinde kıyamet beklentisini dile getiren Yunanca bir yazıt bulunan ve imzalı ile tarihli tek eseri olarak bilinen tablosu hangisidir?', 'Mistik Doğuş', ['Pallas ve Kentaur', 'Müneccimlerin Tapınması', 'Magnificat Meryemi'], '1500 dolaylarında yapılan Mistik Doğuş bugün Londra\'daki Ulusal Galeri\'dedir. Yazıt ve geri dönen Gotik ölçekler, Savonarola sonrası Botticelli\'nin dinsel kaygılarını yansıtır.'),
  ('Rönesans fresklerinde mavi gökyüzü ya da Meryem\'in mavi mantosu gibi alanların bugün çoğu zaman dökülmüş ya da kararmış olmasının başlıca nedeni nedir?', 'Mavi pigmentlerin kuru sıvaya tutkallı bağlayıcıyla sonradan sürülmesi', ['Mavi alanların her zaman ilk gün boyanıp en uzun güneş alması', 'Mavinin kireçle birleşip zamanla kırmızıya dönmesi', 'Bu alanların bilerek ince ve yarı saydam bırakılması'], 'Azurit ve ultramarin yaş kireçle iyi bağlanmadığından çoğu zaman \'secco\' tekniğiyle eklenirdi. Bu katmanlar yaş fresk kadar kalıcı olmadığı için zamanla döküldü.'),
  ('Erken Hollanda resmine ait panoların yapım tarihi çoğu zaman ağaç halkası analiziyle (dendrokronoloji) daraltılabilir. Bu yöntemin bu panolarda iyi işlemesinin temel nedeni nedir?', 'Panoların çoğunun Baltık bölgesinden gelen meşeden yapılması', ['Panoların hep tek bir ağaç gövdesinden kesilmesi', 'Ressamların panonun arkasına kesim yılını yazması', 'Panoların ince kavak tabakalarından yapıştırılması'], 'Meşe belirgin yıllık halkalar oluşturur ve Baltık meşesi için ayrıntılı halka kronolojileri vardır. En dıştaki halkanın tarihi, panonun en erken ne zaman boyanmış olabileceğini gösterir.'),
  ('Rönesans Floransa\'sında ressamlar, pigmentleri sağlayan meslek grubuyla ilişkisi nedeniyle hangi loncaya bağlıydı?', 'Hekimler ve baharatçılar loncası', ['Yün tüccarları loncası', 'Kuyumcular loncası', 'Taş ve ahşap ustaları loncası'], 'Arte dei Medici e Speziali\'ye üye olan baharatçılar boya maddeleri de satardı. Ressamlar bu nedenle hekimlerle aynı loncada yer aldı.'),
  ('Sanat tarihçisi Michael Baxandall\'ın incelemesine göre 15. yüzyıl boyunca İtalyan resim sözleşmelerinde nasıl bir değişim görülür?', 'Malzemenin değerinden çok ustanın kendi elinin ve becerisinin öne çıkması', ['Sözleşmelerin yerini tümüyle sözlü anlaşmalara bırakması', 'Altın ve ultramarin miktarının giderek daha ayrıntılı yazılması', 'Konuyu seçme hakkının bütünüyle ressama bırakılması'], 'Baxandall, sözleşmelerde zamanla figürlerin ustanın kendi eliyle boyanması koşulunun öne çıktığını gösterir. Bu, değerin malzemeden beceriye kaydığını yansıtır.'),
  ('Roma\'da 1593\'te kurulan ve ilk başkanı ressam Federico Zuccari olan sanatçı akademisi hangisidir?', 'Accademia di San Luca', ['Accademia del Disegno', 'Accademia della Crusca', 'Accademia dei Lincei'], 'San Luca Akademisi derslere ve kuramsal tartışmalara yer verdi. Accademia della Crusca dil, Accademia dei Lincei ise bilim akademisidir.'),
  ('Bugün yalnız kopyalardan bilinen Leonardo\'nun \'Anghiari Savaşı\'nın, sancak için dövüşen süvarileri gösteren orta bölümünün en ünlü kopyası Louvre\'daki bir çizimdir. Bu çizimi yapan Barok ustası kimdir?', 'Peter Paul Rubens', ['Nicolas Poussin', 'Anthony van Dyck', 'Annibale Carracci'], 'Rubens, Leonardo\'nun yok olmuş kompozisyonunu daha önceki bir kopyadan yola çıkarak yeniden çizmiştir. Bu çizim, savaşın karmaşık hareketini anlamak için ana kaynaklardan biridir.'),
  ('Suyun hareketi, fosiller ve Ay\'ın soluk ışığı üzerine notlar içeren ve 1994\'te Bill Gates tarafından satın alınan Leonardo defteri hangisidir?', 'Leicester Kodeksi', ['Atlanticus Kodeksi', 'Arundel Kodeksi', 'Madrid Kodeksi'], 'Defter adını 18. yüzyılda onu satın alan Leicester kontlarından alır. Atlanticus Kodeksi Milano\'daki Ambrosiana Kütüphanesi\'ndedir.'),
  ('Leonardo\'nun Milano\'da Francesco Sforza anısına tasarladığı dev bronz at heykeli (\'Gran Cavallo\') hiçbir zaman dökülememiştir. Bunun başlıca nedeni nedir?', 'Ayrılan bronzun Fransız tehdidine karşı top dökümüne verilmesi', ['Kilisenin hayvan heykellerini yasaklaması', 'Leonardo\'nun döküm tekniğini hiç bilmemesi', 'Heykelin dikileceği meydanın büyük bir depremle yıkılıp yapının iptal edilmesi'], 'Bronz 1494\'te Ferrara\'ya top yapımı için gönderildi. Kil model de 1499\'da Milano\'yu alan Fransız askerlerince hedef olarak kullanılıp tahrip edildi.'),
  ('Sigmund Freud\'un 1910\'da Leonardo üzerine yazdığı denemede yorumladığı, Meryem\'in kendi annesinin kucağında oturduğu Leonardo tablosu hangisidir?', 'Azize Anna ile Meryem ve Çocuk İsa', ['Benois Meryemi', 'Kayalıkların Meryemi', 'Karanfilli Meryem'], 'Freud, tablodaki iki anne figürünü Leonardo\'nun çocukluğundaki iki annelik deneyimiyle ilişkilendirdi. Tablo bugün Louvre\'dadır.'),
  ('Milano\'daki Sforza Şatosu\'nda tavanını ve duvarlarını iç içe geçmiş ağaç dalları ve düğümlü iplerle bir çardak gibi boyadığı, Leonardo\'ya atfedilen salon hangisidir?', 'Sala delle Asse', ['Camera degli Sposi', 'Stanza della Segnatura', 'Sala dei Giganti'], 'Sala delle Asse 1498 dolaylarında boyandı. Diğer seçenekler sırasıyla Mantegna\'nın, Raffaello\'nun ve Giulio Romano\'nun ünlü odalarıdır.'),
  ('Leonardo\'nun ölümünden sonra not defterlerini miras alan ve resimle ilgili notlarından \'Resim Üzerine İnceleme\' derlemesini hazırlayan öğrencisi kimdir?', 'Francesco Melzi', ['Gian Giacomo Caprotti', 'Giovanni Antonio Boltraffio', 'Marco d\'Oggiono'], 'Melzi defterleri İtalya\'ya geri götürdü ve resim üzerine notları bir araya getirdi. Ölümünden sonra defterler dağıldı ve farklı koleksiyonlara geçti.'),
  ('Gençliğinde bir tartışma sırasında Michelangelo\'nun burnunu yumrukla kıran ve sonra İngiltere\'de VII. Henry\'nin mezar anıtını yapan Floransalı heykeltıraş kimdir?', 'Pietro Torrigiano', ['Baccio Bandinelli', 'Bertoldo di Giovanni', 'Andrea Sansovino'], 'Olay Brancacci Şapeli\'nde Masaccio fresklerini çizerken yaşandı. Michelangelo\'nun portrelerindeki basık burun bu yaradan kalmıştır.'),
  ('Sistina tavanında Yaratılış sahnelerinin köşelerinde oturan, meşe yaprağı çelenkleri ve madalyonlar taşıyan çıplak genç erkek figürlerine ne ad verilir?', 'Ignudi', ['Putti', 'Sibyller', 'Atlantlar'], 'Meşe yaprakları ve palamutlar, II. Julius\'un ailesi della Rovere\'nin simgesidir (\'rovere\' meşe demektir). Ignudi, Michelangelo\'nun insan bedenine duyduğu hayranlığın en serbest örnekleridir.'),
  ('Michelangelo\'nun son fresklerini yaptığı, Aziz Pavlus\'un dönüşümü ile Aziz Petrus\'un baş aşağı çarmıha gerilişini gösteren Vatikan şapeli hangisidir?', 'Paolina Şapeli', ['Niccolina Şapeli', 'Sistina Şapeli', 'Cerasi Şapeli'], 'Papa III. Paulus için yapılan bu freskler 1542-1550 arasına tarihlenir. Caravaggio da aynı iki konuyu Roma\'daki Cerasi Şapeli için tuvale resmetmiştir.'),
  ('Raffaello\'nun Papa X. Leo\'yu iki kardinal akrabasıyla masa başında gösterdiği Uffizi\'deki portrede, papa süslü bir el yazmasını incelerken elinde hangi nesneyi tutar?', 'Bir büyüteç', ['Gümüş bir haç', 'Bir tespih', 'Bir anahtar'], 'Medici ailesinden gelen X. Leo kitap ve sanat meraklısıydı; görme sorunu da vardı. Büyüteç ve el yazması, papanın bilgin kimliğini vurgular.'),
  ('Hocası Perugino\'nun kompozisyonunu temel alan, arka plandaki çokgen tapınağın kapı kemerine Raffaello\'nun adını ve 1504 tarihini taşıyan Brera Pinakotek\'teki tablo hangisidir?', 'Meryem\'in Evlenmesi', ['Meryem\'in Taç Giymesi', 'Saka Kuşlu Meryem', 'Güzel Bahçıvan Kadın'], '\'Lo Sposalizio\' adıyla bilinen tablo, öğrencinin ustasını mekân derinliği ve figür akıcılığında aştığını gösterir.'),
  ('Raffaello\'nun Sistina Şapeli\'nin duvarlarına asılacak halılar için hazırladığı, Havarilerin İşleri\'nden sahneler içeren büyük boyutlu kartonlar bugün nerededir?', 'Londra\'daki Victoria ve Albert Müzesi\'nde', ['Vatikan\'daki Sistina Şapeli\'nin depolarında', 'Brüksel\'deki Kraliyet Güzel Sanatlar Müzesi\'nde', 'Floransa\'daki Uffizi\'nin çizim kabinesinde'], 'Halılar Brüksel\'de Pieter van Aelst\'in atölyesinde dokundu. Kartonlar 17. yüzyılda İngiltere\'ye geçti ve İngiliz Kraliyet Koleksiyonu\'na aittir.'),
  ('Raffaello\'nun \'La Fornarina\' portresinde göğsünü eliyle örten genç kadının sol kolundaki şeritte ne yazılıdır?', 'Ressamın adı', ['Modelin adı', 'Bir dua cümlesi', 'Tablonun tarihi'], 'Kol bandında \'Raphael Urbinas\' yazar. Geleneksel olarak model, ressamın sevgilisi olduğu söylenen fırıncı kızı Margherita Luti ile özdeşleştirilir.'),
  ('Napoli\'deki Capodimonte Müzesi\'nde bulunan, yaşlı ve kamburlaşmış bir papayı iki torunuyla gösteren, yarım kalmış ve psikolojik gerilimiyle bilinen Tiziano portresi kimi gösterir?', 'Papa III. Paulus\'u', ['Papa II. Julius\'u', 'Papa X. Leo\'yu', 'Papa VII. Clemens\'i'], 'Farnese ailesinden III. Paulus, torunları Alessandro ve Ottavio ile gösterilir. Eğilen torunun yaltaklanan tavrı, sahneye saray entrikası havası verir.'),
  ('Tiziano\'nun İspanya Kralı II. Felipe için Ovidius\'un \'Dönüşümler\'inden yola çıkarak yaptığı mitolojik tablo dizisine ressamın kendisi hangi adı vermiştir?', 'Poesie', ['Capricci', 'Vedute', 'Bambocciate'], 'Tiziano bu tabloları görsel şiirler olarak tanımlıyordu. Dizide Diana ve Aktaion ile Europa\'nın Kaçırılışı gibi eserler yer alır.'),
  ('Tiziano\'nun kendi mezar şapeli için yaptığı ve 1576\'da veba salgınında ölmesinin ardından Palma il Giovane\'nin tamamladığı son büyük tablosu hangisidir?', 'Pietà', ['Assunta', 'Pesaro Meryemi', 'Kutsal ve Dünyevi Aşk'], 'Tablo bugün Venedik\'teki Accademia Galerisi\'ndedir. Yazıtta Palma il Giovane\'nin eseri saygıyla bitirdiği belirtilir.'),
  ('Roma\'ya yerleşip Michelangelo\'nun çizimlerini kullanarak Raffaello\'ya rakip tablolar yapan ve lakabını papalık mühür dairesindeki görevinden alan Venedikli ressam kimdir?', 'Sebastiano del Piombo', ['Lorenzo Lotto', 'Palma il Vecchio', 'Giulio Pippi'], '\'Piombo\' kurşun demektir; papalık belgelerine basılan kurşun mühürlerden sorumlu göreve atanmıştı. Venedik rengini Michelangelo\'nun figürleriyle birleştirdi.'),
  ('Louvre\'daki, bir küvette yan yana oturan iki çıplak kadından birinin ötekinin göğüs ucunu parmaklarıyla tuttuğu 16. yüzyıl sonu anonim tablosu hangi okula atfedilir?', 'Fontainebleau Okulu', ['Utrecht Caravaggistleri', 'Bolonya Okulu', 'Tuna Okulu'], 'Tablonun modellerinin IV. Henri\'nin gözdesi Gabrielle d\'Estrées ve kız kardeşi olduğu düşünülür. Jest çoğunlukla Gabrielle\'in gebeliğine bir gönderme olarak yorumlanır.'),
  ('Bronzino\'nun Londra\'daki karmaşık simgeli \'Venüs ve Kupid\'li Alegori\' tablosu, I. Cosimo de\' Medici tarafından kime armağan olarak gönderilmiştir?', 'Fransa Kralı I. François\'ya', ['İmparator V. Karl\'a', 'Papa III. Paulus\'a', 'İngiltere Kralı VIII. Henry\'ye'], 'Tablo diplomatik bir armağandı. Kıskançlık, Zaman ve Aldatma gibi kişileştirmeler içeren şifreli kompozisyonu, maniyerist saray kültürünün entelektüel oyunlarını yansıtır.'),
  ('Shakespeare\'in \'Kış Masalı\' oyununda adı geçen ve böylece Shakespeare\'in eserlerinde anılan tek Rönesans sanatçısı olan İtalyan kimdir?', 'Giulio Romano', ['Michelangelo Buonarroti', 'Raffaello Sanzio', 'Tiziano Vecellio'], 'Oyunda Hermione\'nin heykelinin \'ender İtalyan usta Giulio Romano\' tarafından yapıldığı söylenir. Giulio aslında ressam ve mimar olarak tanınır.'),
  ('Floransa\'daki Signoria Meydanı\'nda bulunan ve halkın \'Biancone\' (koca beyaz) lakabını taktığı mermer deniz tanrısı heykelli çeşmeyi yapan heykeltıraş kimdir?', 'Bartolomeo Ammannati', ['Baccio Bandinelli', 'Benvenuto Cellini', 'Giambologna'], 'Neptün Çeşmesi 1560\'larda yapıldı. Michelangelo\'nun Davut\'unun yakınında duran heykel, beyaz ve iri gövdesi nedeniyle alay konusu olmuştur.'),
  ('Signoria Meydanı\'nda Davut\'un yanında duran \'Herkül ve Kakus\' grubunu yapan ve rakibi Cellini\'nin bu heykeli \'bir çuval kavun\'a benzeterek alay ettiği heykeltıraş kimdir?', 'Baccio Bandinelli', ['Bartolomeo Ammannati', 'Vincenzo Danti', 'Niccolò Tribolo'], 'Bandinelli, Michelangelo ile yarışma iddiasındaydı ama eseri sert eleştirilere uğradı. Cellini\'nin alayı, onun ünlü otobiyografisinde aktarılır.'),
  ('Cellini\'nin anlattığına göre Perseus heykelinin dökümü sırasında eriyik metal katılaşmaya başlayınca kalıbı kurtarmak için ne yapmıştır?', 'Evindeki kalay tabak ve kapları eritme ocağına atmıştır', ['Kalıbı soğuk suyla ıslatarak çatlamasını önlemiştir', 'Dökümü bırakıp heykeli mermerden yontmaya karar vermiştir', 'Eksik kalan bölümü sonradan alçıyla tamamlamıştır'], 'Kalay, alaşımı akışkanlaştırarak dökümün tamamlanmasını sağladı. Cellini yalnız bir ayağın eksik çıktığını ve sonradan eklendiğini anlatır.'),
  ('Arcimboldo\'nun \'Sebze Bahçıvanı\' tablosu bir yönden bakıldığında kâse içinde sebzelerden oluşan bir natürmorttur. Tablo ters çevrilince ne görünür?', 'Bir insan başı', ['Bir bahçe manzarası', 'Bir kent görünümü', 'Bir çiçek vazosu'], 'Ters çevrilebilir bu resimde kâse şapkaya, sebzeler yüzün ayrıntılarına dönüşür. Arcimboldo böylece natürmort ile portreyi tek görüntüde birleştirir.'),
  ('Robert Campin\'e atfedilen Mérode Sunağı\'nın sağ kanadında marangoz Yusuf\'un fare kapanları yaptığı görülür. Bu ayrıntı genellikle nasıl yorumlanır?', 'İsa\'nın insan oluşunun şeytanı yakalayan bir tuzak olduğu düşüncesiyle', ['Yusuf\'un yoksulluğunu ve aç kalan bir aileyi anlatan gerçekçi bir ayrıntı olarak', 'Evin farelerle dolu olmasının Meryem\'in ihmalini göstermesi biçiminde', 'Bağışçı ailenin fare kapanı ticaretiyle zenginleştiğinin işareti olarak'], 'Aziz Augustinus, Mesih\'in bedenini şeytan için kurulmuş bir fare kapanına benzetmişti. Gündelik nesneler bu yolla gizli bir dinsel anlam taşır.'),
  ('Belgelerde adı geçmeyen eserler üzerinden adlandırılan ve bugün çoğunlukla Tournai\'li Robert Campin ile özdeşleştirilen erken Hollandalı ressama hangi geçici ad verilmiştir?', 'Flémalle Ustası', ['Ölüm Ustası', 'Aziz Bartholomeus Ustası', 'Moulins Ustası'], 'Bu ad, yanlışlıkla Flémalle\'den geldiği sanılan birkaç panodan türetildi. Campin, Rogier van der Weyden\'in de hocası olarak kabul edilir.'),
  ('Jan van Eyck\'in bazı tablolarının çerçevesine yazdığı ve kendi adıyla söz oyunu yapan alçakgönüllü slogan hangisidir?', 'Als ich can (Elimden geldiğince)', ['Nulla dies sine linea', 'Ars longa, vita brevis (Sanat uzun, yaşam kısa)', 'Festina lente'], 'Flamanca \'ich\' ile \'Eyck\' arasında ses benzerliği vardır. Slogan, ustanın becerisini alçakgönüllülük kılığında öne çıkarır.'),
  ('Ghent Sunağı\'nın 1934\'te çalınan ve bugüne dek bulunamayan panosu hangisidir?', 'Adil Yargıçlar', ['Mesih\'in Şövalyeleri', 'Âdem ve Havva', 'Şarkı Söyleyen Melekler'], 'Çalınan panonun yerinde bugün 1940\'larda yapılmış bir kopya durur. Hırsızlık ve fidye mektupları, Belçika\'da hâlâ merak konusu olan bir gizemdir.'),
  ('II. Dünya Savaşı\'nda Nazilerin el koyduğu Ghent Sunağı, 1945\'te \'Anıt Adamlar\' diye anılan Müttefik birlikleri tarafından nerede bulunmuştur?', 'Avusturya\'daki Altaussee tuz madeninde', ['Berlin\'deki Reichstag\'ın bodrumunda', 'Münih\'teki Führerbau binasının çelik kasa dairesinde', 'Bavyera\'daki Neuschwanstein Şatosu\'nda'], 'Altaussee\'de binlerce sanat eseri saklanmıştı. Sunak kurtarılarak Belçika\'ya iade edildi.'),
  ('Burgonya şansölyesi Nicolas Rolin\'in Beaune\'da kurduğu hastane için yapılan, hastaların yataklarından görebileceği biçimde yerleştirilen büyük \'Son Yargı\' poliptiğinin ressamı kimdir?', 'Rogier van der Weyden', ['Hans Memling', 'Jan van Eyck ve kardeşi Hubert', 'Dirk Bouts'], 'Poliptik bugün de Beaune\'daki Hôtel-Dieu\'dedir. Ortada terazisiyle ruhları tartan Başmelek Mikail yer alır.'),
  ('Floransa\'ya gönderilirken 1473\'te bir Hansa korsanı tarafından gemiyle birlikte ele geçirilen ve bugün Gdańsk\'ta bulunan \'Son Yargı\' triptiğinin ressamı kimdir?', 'Hans Memling', ['Rogier van der Weyden', 'Hugo van der Goes', 'Petrus Christus'], 'Triptik Medici bankasının temsilcisi Angelo Tani için yapılmıştı. Korsan Paul Beneke onu Danzig\'deki Meryem Kilisesi\'ne bağışladı.'),
  ('Leuven\'deki Aziz Petrus Kilisesi\'nin \'Kutsal Ayin Sunağı\'nda Son Akşam Yemeği\'ni tek kaçış noktalı perspektifle kuran ilk Kuzeyli ressamlardan biri kimdir?', 'Dirk Bouts', ['Gerard David', 'Hugo van der Goes', 'Joos van Cleve'], 'Bouts\'un 1460\'lardaki bu sunağı, İtalyan tarzı tutarlı perspektifin Kuzey\'de erken uygulamalarındandır. İsa\'nın başı yine anlam merkezinde tutulur.'),
  ('Geniş, kuşbakışı, kayalık ve nehirli \'dünya manzarası\' türünü geliştiren ve Dürer\'in \'iyi manzara ressamı\' diye övdüğü Anversli ressam kimdir?', 'Joachim Patinir', ['Herri met de Bles', 'Jan Gossaert', 'Joos van Cleve'], 'Patinir\'in tablolarında dinsel figürler küçülür, manzara ana konu hâline gelir. Bu yaklaşım bağımsız manzara resminin doğuşunda önemli bir adımdır.'),
  ('Brugge belediye binası için yapılan, rüşvet alan yargıç Sisamnes\'in diri diri derisinin yüzülmesini gösteren ibret tablosunun ressamı kimdir?', 'Gerard David', ['Hans Memling', 'Dirk Bouts', 'Quentin Matsys'], '\'Kambises\'in Yargısı\' adlı bu diptik, yargıçlara dürüstlüğü hatırlatmak için duruşma salonuna asılmıştı. Antik Herodotos anlatısına dayanır.'),
  ('1508\'de Roma\'ya giderek antik kalıntıları çizen ve dönüşünde Hollanda resmine mitolojik çıplak figürleri getirerek \'Romanist\' akımın öncüsü olan ressam kimdir?', 'Jan Gossaert', ['Joachim Patinir', 'Lucas van Leyden', 'Pieter Coecke van Aelst'], 'Gossaert, Burgonya prensi Philippe\'in maiyetinde Roma\'ya gitti. Neptün ve Amphitrite gibi eserleri Kuzey\'de antik çıplaklığın erken örnekleridir.'),
  ('New York\'taki Metropolitan Müzesi\'nde bulunan Bruegel\'in \'Ekin Biçenler\' tablosu hangi dizinin parçasıdır?', 'Anversli bir tüccar için yapılan altı tabloluk mevsimler dizisi', ['Habsburg imparatoru için yapılan on iki aylık takvim dizisi', 'Bir matbaacı için çizilen yedi ölümcül günah dizisi', 'Brüksel katedrali için yapılan dört İncil yazarı ve dört kilise babası dizisi'], 'Dizi 1565\'te Niclaes Jongelinck için yapıldı ve beş tablosu günümüze ulaştı. \'Kardaki Avcılar\' da aynı dizinin parçasıdır.'),
  ('Bruegel\'in Viyana\'daki \'Köylü Düğünü\' tablosunda kalabalık bir ambarda gelin nasıl ayırt edilir?', 'Yeşil bir örtünün önünde, başında kâğıt bir taçla oturan kadın olarak', ['Kapıdan girerken bir buket taşıyan kadın olarak', 'Ortada dans ederken beyaz bir duvak takan ve çiçeklerle süslü kadın olarak', 'Masanın başında kadeh kaldıran kadın olarak'], 'Gelin yemek yemez, elleri kavuşmuş biçimde oturur. Damadın kim olduğu ise tablodan kesin olarak anlaşılamaz.'),
  ('Dürer\'in 1513-1514 yıllarında yaptığı ve \'Ustalık Gravürleri\' adıyla \'Melankoli I\' ile birlikte anılan diğer iki bakır gravür hangileridir?', 'Şövalye, Ölüm ve Şeytan ile Çalışma Odasında Aziz Hieronymus', ['Âdem ile Havva (1504) ile Kıyamet dizisinden Mahşerin Dört Atlısı', 'Büyük Talih ile Küçük Talih', 'Dua Eden Eller ile Genç Tavşan'], 'Üç gravür bilinçli bir dizi olmasa da teknik mükemmellikleri nedeniyle birlikte anılır. Eylemli, dinsel ve düşünsel yaşamın üç biçimini temsil ettikleri yorumlanır.'),
  ('Vasari\'ye göre Marcantonio Raimondi, Dürer\'in baskılarını \'AD\' monogramıyla birlikte kopyalayıp satınca Dürer Venedik\'te şikâyette bulunmuştur. Sonuç ne olmuştur?', 'Kopyalara izin verilmiş, ama monogramın kullanılması yasaklanmıştır', ['Raimondi\'nin tüm baskıları kent meydanında yakılmış ve atölyesi süresiz kapatılmıştır', 'Dürer şikâyetini kaybedip para cezasına çarptırılmıştır', 'Raimondi Dürer\'e ortak olarak alınıp kâr paylaşılmıştır'], 'Bu olay, sanatsal imza ve fikrî mülkiyetin erken bir tartışması olarak anılır. Kompozisyonu kopyalamak serbest, ustanın işaretini taklit etmek yasak sayıldı.'),
  ('Dürer\'in 1506\'da Venedik\'te, San Bartolomeo Kilisesi\'ndeki Alman tüccarları için yaptığı ve Giovanni Bellini\'nin de hayranlığını kazandığı anlatılan sunak resmi hangisidir?', 'Gül Çelenkleri Bayramı', ['Dört Havari', 'Heller Sunağı', 'Müneccimlerin Tapınması'], 'Tabloda Meryem, imparator ve papaya gül çelenkleri dağıtır. Dürer arka planda bir yazı tutarak kendini de resmetmiştir; eser bugün Prag\'dadır.'),
  ('Dürer\'in 1520-1521 Hollanda yolculuğu günlüğünde \'ömrümde bu kadar sevindirici bir şey görmedim\' diye yazdığı, Brüksel\'de sergilenen eşyalar nereden gelmişti?', 'Meksika\'dan V. Karl\'a gönderilen Aztek hazinelerinden', ['Hindistan\'dan Portekiz kralına gelen baharat ve fildişi eşyalarından', 'Osmanlı sarayından armağan edilen halı ve kaftanlardan', 'Çin\'den getirilen porselen ve ipek koleksiyonundan'], 'Hernán Cortés\'in gönderdiği altın güneş diski ve silahları gören Dürer, uzak ustaların \'ince dehası\'nı övmüştür. Bu not, Avrupalı bir sanatçının Amerika sanatına ilk tepkilerindendir.'),
  ('Lucas Cranach\'ın atölyesinden çıkan tablolarda imza yerine kullanılan ve Saksonya seçicisinin verdiği armadan gelen simge hangisidir?', 'Ağzında yüzük taşıyan kanatlı yılan', ['Kılıç tutan bir aslan', 'Üç çivili bir haç', 'Taç giymiş bir kartal'], 'Cranach büyük bir atölye yönetiyor, tabloları seri hâlde üretiyordu. Simgedeki kanatların biçiminin değişmesi, eserleri tarihlendirmeye yardım eder.'),
  ('Lucas Cranach\'ın Luther\'le birlikte geliştirdiği, bir ağacın iki yanında \'Yasa\' ile \'Lütuf\'u karşılaştıran resim tipi hangi düşünceyi görselleştirir?', 'Kurtuluşun iyi işlerle değil, imanla ve Tanrı\'nın lütfuyla geldiği düşüncesini', ['Kilisenin satın alınabilir endüljanslarla günahları bağışladığı inancını', 'Azizlere yakarmanın kurtuluşun tek yolu olduğu öğretisini', 'Eski Ahit yasasının Hristiyanlar için hiçbir değişiklik olmadan tümüyle geçerli olduğu görüşünü'], 'Sol yarıda Musa\'nın yasası insanı cehenneme sürükler; sağ yarıda çarmıhtaki İsa\'nın kanı inanana ulaşır. Tablo Protestan öğretisinin görsel bir özetidir.'),
  ('Ihlamur ağacından oyduğu boyasız sunaklarıyla tanınan ve 1525 Köylü Savaşı\'nda isyancılara destek verdiği için hapsedilen Würzburglu heykeltıraş kimdir?', 'Tilman Riemenschneider', ['Veit Stoss', 'Adam Kraft', 'Peter Vischer'], 'Riemenschneider, sunaklarını boyamadan bırakarak ahşabın dokusuyla ışık-gölge etkisi yaratan ilk ustalardandı. Creglingen\'deki Meryem Sunağı en ünlü işlerindendir.'),
  ('Krakow\'daki Meryem Bazilikası\'nda bulunan, on metreyi aşan yüksekliği ve boyalı ahşap figürleriyle Avrupa\'nın en büyük Gotik sunaklarından sayılan eseri oyan Nürnbergli usta kimdir?', 'Veit Stoss', ['Tilman Riemenschneider', 'Michael Pacher', 'Hans Leinberger'], 'Sunak 1477-1489 arasında yapıldı. Meryem\'in ölümünü gösteren orta bölümdeki havari figürleri insan boyundan büyüktür.'),
  ('Farklı tonlarda boyanan birden çok ahşap kalıbın üst üste basılmasıyla ışık ve gölge etkisi veren, İtalya\'da Ugo da Carpi\'nin geliştirdiği baskı türüne ne ad verilir?', 'Kiyaroskuro ağaç baskı', ['Kuru kazıma', 'Mezzotint', 'Akuatint'], 'Bir kalıp çizgiyi, diğerleri ara tonları ve ışıkları verir. Böylece çizimlerin yıkanmış mürekkep etkisi baskıyla taklit edilebildi.'),
  ('Gençlik yıllarında usta bir gravürcü olarak ün kazanan ve 1521\'de Anvers\'te Dürer\'le tanışarak karşılıklı portrelerini çizdikleri Hollandalı sanatçı kimdir?', 'Lucas van Leyden', ['Jan van Scorel', 'Maarten van Heemskerck', 'Hendrick Goltzius'], 'Lucas van Leyden, Dürer\'in en önemli Kuzeyli rakibi sayılırdı. Dürer günlüğünde ondan söz eder ve portresini gümüş uçla çizmiştir.'),
  ('1969\'da Palermo\'daki San Lorenzo Oratoryosu\'ndan çalınan ve bugün hâlâ bulunamamış olan Caravaggio tablosu hangisidir?', 'Azizler Franciscus ve Laurentius ile Doğuş', ['Kâhin Kadın', 'Kumarbaz Hileciler', 'Lavtalı Genç'], 'Hırsızlığın Sicilya mafyasıyla bağlantılı olduğu düşünülür. Oratoryoda bugün tablonun dijital bir kopyası asılıdır.'),
  ('Genç Caravaggio\'yu Roma\'daki sarayına alan ve \'Müzisyenler\' ile \'Lavtalı Genç\' gibi tabloları yapmasını destekleyen kardinal kimdir?', 'Francesco Maria del Monte', ['Scipione Borghese', 'Ferdinando de\' Medici', 'Federico Borromeo'], 'Del Monte, müzik ve bilimle ilgilenen kültürlü bir kardinaldi. San Luigi dei Francesi\'deki büyük kamusal siparişi Caravaggio\'ya kazandırmasında da etkili oldu.'),
  ('Caravaggio 1610\'da papalık affını beklerken Roma\'ya dönmeye çalışırken nerede ölmüştür?', 'Toskana kıyısındaki Porto Ercole\'de', ['Malta\'daki Valletta\'da', 'Napoli\'deki Spagnoli mahallesinde', 'Sicilya\'daki Siraküza\'da'], 'Napoli\'den yola çıkan ressam kıyıda tutuklandı, eşyalarını içeren tekne yola devam etti. Ateşli bir hastalıkla otuz sekiz yaşında öldü.'),
  ('Annibale ile Agostino Carracci kardeştir. Bolonya\'daki akademiyi onlarla birlikte kuran Ludovico Carracci onların neyidir?', 'Kuzeni', ['Babası', 'Amcası', 'Ağabeyi'], 'Ludovico, Annibale ile Agostino\'dan birkaç yaş büyük kuzenleriydi. Üçü 1580\'lerde canlı model çalışmasına dayanan akademiyi birlikte kurdu.'),
  ('Agostino Carracci\'nin aynı konudaki tablosuna çok benzediği için intihal suçlamasına uğrayan, ama Poussin\'in en büyük resimlerden saydığı Domenichino tablosu hangisidir?', 'Aziz Hieronymus\'un Son Komünyonu', ['Azize Cecilia\'nın Ölümü', 'Diana\'nın Avı', 'Aziz Andreas\'ın Kırbaçlanması'], 'Tablo bugün Vatikan Pinakotekası\'ndadır. Tartışma, dönemin özgünlük ve ustaya öykünme anlayışlarının çatıştığını gösterir.'),
  ('Roma\'daki Il Gesù Kilisesi\'nin tavanında, boyalı figürlerin çerçeveden taşıp alçı bulutlar üzerinden aşağı düşüyormuş gibi göründüğü \'İsa Adının Zaferi\' freskini kim yapmıştır?', 'Giovanni Battista Gaulli', ['Pietro da Cortona', 'Andrea Pozzo', 'Giovanni Lanfranco'], 'Gaulli resim, alçı ve mimariyi birleştirerek göğün kiliseye taştığı bir yanılsama kurdu. Bernini\'nin desteğini alan genç ressam bu işi 1670\'lerde tamamladı.'),
  ('1612\'de Roma\'da ressam Agostino Tassi\'ye karşı açılan davada, Artemisia Gentileschi\'nin tanıklığının doğruluğunu sınamak için ne yapılmıştır?', 'Parmaklarına vida ile işkence uygulanmıştır', ['Bir din adamı önünde İncil\'e yemin ettirilmiştir', 'Tanıklığı yazılı bir resim sınavıyla doğrulanmıştır', 'Ailesinin mal varlığı teminat olarak alınmıştır'], 'O dönemin mahkemelerinde tanığın doğruyu söylediğini kanıtlamak için işkence uygulanabiliyordu. Tassi suçlu bulunmuş, ama cezası pek uygulanmamıştır.'),
  ('Bolonya\'da büyük sunak resimleri ısmarlanan, papalık çevresi için de çalışan ve on bir çocuğu olduğu hâlde ailesini resim gelirleriyle geçindiren 16. yüzyıl kadın ressamı kimdir?', 'Lavinia Fontana', ['Sofonisba Anguissola', 'Elisabetta Sirani', 'Fede Galizia'], 'Fontana, saray ya da manastır dışında profesyonel kariyer yapan ilk kadın ressamlardan sayılır. Kocası onun asistanlığını üstlenmiştir.'),
  ('Bolonya\'da kadın sanatçılar için bir resim okulu açan, çok hızlı çalışmasıyla tanınan ve 1665\'te yirmi yedi yaşında ölen Barok ressam kimdir?', 'Elisabetta Sirani', ['Lavinia Fontana', 'Ginevra Cantofoli', 'Giovanna Garzoni'], 'Sirani\'nin babası da ressamdı. Kısa yaşamında iki yüzü aşkın tablo yaptığı kayıtlarından anlaşılır.'),
  ('Bernini\'nin geç döneminde Roma\'daki San Francesco a Ripa Kilisesi için yaptığı, ölüm döşeğinde vecd içinde uzanan kutsanmış bir kadını gösteren heykel hangisidir?', 'Kutsanmış Ludovica Albertoni', ['Azize Bibiana', 'Azize Agnes', 'Azize Cecilia'], 'Bu eser, Bernini\'nin ışık, örtü kıvrımları ve mimariyi birleştirdiği son büyük heykel düzenlemelerindendir. Teresa\'dan yaklaşık yirmi beş yıl sonra yapılmıştır.'),
  ('Roma\'daki İspanyol Merdivenleri\'nin dibinde bulunan, yarı batık bir tekne biçimindeki Barcaccia Çeşmesi\'ni oğlunun da yardımıyla yapan heykeltıraş kimdir?', 'Pietro Bernini', ['Carlo Maderno', 'Giacomo della Porta', 'Stefano Maderno'], 'Çeşme 1620\'lerde tamamlandı. Düşük su basıncı nedeniyle yüksek fıskiyeler yerine yere gömülü, taşan bir tekne biçimi seçilmiştir.'),
  ('Bernini\'nin mimarlık, heykel ve resmi ışıkla birleştirerek tek ve bütünlüklü bir etki yaratma anlayışına sanat tarihinde hangi ad verilir?', 'Bel composto', ['Gesamtkunstwerk', 'Disegno interno', 'Sprezzatura'], '\'Güzel bütün\' anlamına gelen bu kavram, Bernini\'nin biyografi yazarı Filippo Baldinucci\'den gelir. Cornaro Şapeli bu anlayışın en ünlü örneğidir.'),
  ('1599\'da mezarı açıldığında bozulmamış hâlde bulunduğu anlatılan Azize Cecilia\'yı, yan yatmış ve boynundaki kesik görünür biçimde gösteren mermer heykelin sanatçısı kimdir?', 'Stefano Maderno', ['Alessandro Algardi', 'Pietro Bernini', 'Francesco Mochi'], 'Maderno\'nun 1600 tarihli heykeli Roma\'daki Santa Cecilia in Trastevere\'dedir. Azizenin yüzü yere dönüktür ve heykel bir mezar tanıklığı gibi tasarlanmıştır.'),
  ('Aziz Petrus Bazilikası\'nda, Papa I. Leo\'nun Hun hükümdarı Attila\'yı Roma\'yı yağmalamaktan vazgeçirdiğini gösteren dev mermer kabartmayı yapan Bernini\'nin rakibi heykeltıraş kimdir?', 'Alessandro Algardi', ['Francesco Duquesnoy', 'Ercole Ferrata', 'Antonio Raggi'], 'Algardi\'nin kabartması yağlı boya sunak resmi yerine konmuş büyük bir heykeldir. Ölçülü ve klasik üslubu, Bernini\'nin coşkulu tarzına karşı bir seçenek sunar.'),
  ('Fransız heykeltıraş Pierre Puget\'nin Louvre\'daki ünlü eserinde, eli bir ağaç gövdesinin yarığına sıkışmışken bir aslanın saldırısına uğrayan antik güreşçi kimdir?', 'Krotonlu Milon', ['Herakles', 'Samson', 'Laokoon'], 'Efsaneye göre Milon gücünü sınamak için bir ağacı yarmak istemiş, eli sıkışınca vahşi hayvanlara yem olmuştur. Puget\'nin acıyla bükülen figürü Barok\'un dramatik yönünü yansıtır.'),
  ('Brüksel\'in simgesi olan küçük bronz \'Manneken Pis\' heykelinin 1619\'da yapımı hangi heykeltıraşa atfedilir?', 'Jérôme Duquesnoy', ['François Duquesnoy', 'Artus Quellinus', 'Hendrick de Keyser'], 'Bugün yerinde bir kopya durur. Heykeltıraşın oğlu François Duquesnoy, Roma\'da \'Il Fiammingo\' lakabıyla ünlenmiş ve Aziz Petrus\'taki Aziz Andreas heykelini yapmıştır.'),
  ('Velázquez\'in 1630\'daki ilk İtalya yolculuğunda yaptığı, ışıklı Apollon\'un demirci tanrıya karısının ihanetini haber verdiği tablo hangisidir?', 'Vulcanus\'un Demirhanesi', ['Mars\'ın Dinlenmesi', 'Merkür ve Argus', 'Apollon\'un Zaferi'], 'Tablo Velázquez\'in İtalyan çıplak figür ve mekân anlayışını özümsediğini gösterir. Haber karşısında donup kalan demircilerin yüzleri güçlü bir psikolojik an yakalar.'),
  ('Velázquez, 1660\'ta ölümünden kısa süre önce saray mareşali olarak hangi önemli törenin düzenlemesini üstlenmişti?', 'İspanyol Infanta María Teresa ile XIV. Louis\'nin evlilik buluşması', ['IV. Felipe\'nin Kastilya kralı olarak taç giyme töreni', 'Breda kentinin teslim alınma töreni', 'Papa X. Innocentius\'un Madrid\'e yaptığı resmî ziyaret'], 'Fransa ile İspanya sınırındaki Sülün Adası\'nda yapılan tören yorucu bir hazırlık gerektirdi. Velázquez dönüşte hastalanıp birkaç hafta sonra öldü.'),
  ('Taş bir pencere çerçevesinde ipe asılı ayva ve lahananın, kenarda kavun ve salatalığın matematiksel bir eğri üzerinde dizildiği ünlü İspanyol natürmortunu yapan, sonradan Kartuziyen keşişi olan ressam kimdir?', 'Juan Sánchez Cotán', ['Juan van der Hamen', 'Francisco de Zurbarán', 'Luis Meléndez'], 'Sánchez Cotán\'ın natürmortları karanlık boşluk önünde neredeyse mistik bir dinginlik taşır. San Diego\'daki tablo bu türün en tanınmış örneğidir.'),
  ('Sevilla\'daki Caridad Hastanesi için \'Göz açıp kapayıncaya dek\' (In ictu oculi) ve \'Dünya şanının sonu\' (Finis gloriae mundi) başlıklı ürkütücü vanitas tablolarını yapan ressam kimdir?', 'Juan de Valdés Leal', ['Bartolomé Esteban Murillo', 'Antonio de Pereda', 'Alonso Cano'], 'Tablolarda bir iskelet mumu söndürür, çürüyen cesetler kiliseye gömülür. Hastanenin kurucusu Miguel de Mañara bu dizi ile ölüm üzerine düşünmeyi amaçlamıştı.'),
  ('José de Ribera\'nın Louvre\'daki \'Topal Çocuk\' tablosunda gülümseyen yoksul oğlanın elinde tuttuğu kâğıtta ne yazar?', 'Tanrı aşkına bana sadaka verin', ['Bu kâğıdı taşıyan kişi azat edilmiştir', 'Napoli kralı çok yaşa', 'Ölüm herkese gelir'], 'Latince yazı, çocuğun konuşma engelli olabileceğini ve dilenmek için izin belgesi taşıdığını düşündürür. Ribera yoksulluğu acıma yerine saygıyla gösterir.'),
  ('İspanyol ahşap heykellerinde giysilerin önce altın varakla kaplanıp üzerine boya sürüldükten sonra boyanın desen biçiminde kazınarak altının açığa çıkarılması tekniğine ne ad verilir?', 'Estofado', ['Esgrafiado sobre yeso', 'Encarnación', 'Enkaustik'], 'Estofado, kumaşların brokar gibi parıldamasını sağlar. Ten bölgelerinin gerçekçi boyanmasına ise \'encarnación\' denir.'),
  ('Çağdaşlarının \'ahşabın tanrısı\' diye övdüğü, Sevilla\'da boyalı ahşaptan sunak ve alay heykelleri yapan heykeltıraş kimdir?', 'Juan Martínez Montañés', ['Gregorio Fernández', 'Pedro de Mena', 'Alonso Berruguete'], 'Montañés\'in heykellerini çoğu zaman Pacheco gibi ressamlar boyardı. \'Merhametli İsa\' adlı çarmıh heykeli en tanınan eseridir.'),
  ('El Greco\'nun Toledo Katedrali için yaptığı \'İsa\'nın Giysilerinin Çıkarılması\' (El Expolio) tablosu katedral yönetimiyle bir anlaşmazlığa yol açmıştır. Bu anlaşmazlığın nedenlerinden biri hangisidir?', 'Kalabalık başların İsa\'nın başından yukarıda gösterilmesi', ['Tablonun anlaşmada belirtilenden çok küçük yapılması', 'İsa\'nın yüzünün bir Venedikli tüccara benzetilmesi', 'Sahnenin tümüyle grisaille tekniğiyle boyanması'], 'Katedral rahipleri, figürlerin İsa\'dan yüksekte durmasını ve İncil\'de bu sahnede geçmeyen Meryemlerin eklenmesini uygunsuz buldu. Ücret konusunda da mahkemeye gidildi.'),
  ('İspanya Kralı II. Felipe\'nin beğenmeyerek Escorial Sarayı\'ndaki yerine başka bir ressamın tablosunu koydurduğu El Greco eseri hangisidir?', 'Aziz Mauritius\'un Şehitliği', ['Kont Orgaz\'ın Gömülmesi', 'Meryem\'in Göğe Yükselişi', 'Kutsal Üçleme'], 'Kralın sözünü ettiği kusur, şehitlik sahnesinin arka plana itilip askerlerin tartışmasının öne çıkarılmasıydı. Bu ret, El Greco\'nun saray ressamı olma umudunu sona erdirdi.'),
  ('El Greco\'nun günümüze ulaşan tek mitolojik tablosu olan, arka planında Toledo\'nun göründüğü ve yılanlarla boğuşan bir rahiple oğullarını gösteren eser hangisidir?', 'Laokoon', ['Prometheus', 'Herakles ile Hydra', 'Orpheus ve Eurydike'], 'Antik Laokoon heykel grubunun 1506\'da Roma\'da bulunması bu konuya ilgiyi artırmıştı. El Greco öyküyü Truva yerine Toledo\'nun önünde geçirir.'),
  ('Rubens 1600-1608 yıllarında İtalya\'da kimin saray ressamı olarak çalışmış, bu sırada Roma, Venedik ve İspanya\'ya da gitmiştir?', 'Mantova Dükü Vincenzo Gonzaga\'nın', ['Toskana Grandükü I. Ferdinando de\' Medici\'nin', 'Venedik Doçu Leonardo Donà\'nın', 'Savoia Dükü I. Carlo Emanuele\'nin'], 'Gonzaga hizmeti Rubens\'e İtalyan sanatını yakından inceleme olanağı verdi. 1603\'te dük adına İspanya\'ya diplomatik bir armağan götürdü.'),
  ('Rubens\'in yaşamının son yıllarında satın aldığı ve geç dönem manzaralarına konu ettiği Brabant\'taki kır malikânesinin adı nedir?', 'Het Steen', ['Rubenshuis', 'Kasteel van Gaasbeek', 'Mariemont'], 'Het Steen\'den bakan geniş sonbahar manzarası, Rubens\'in yalnızca kendisi için yaptığı resimlerin örneğidir. Tablo bugün Londra\'daki Ulusal Galeri\'dedir.'),
  ('Meyhanelerde tütün içen, kavga eden ve acı ilaç içerken yüzünü buruşturan köylüleri küçük tablolarda gösteren, eserlerini Rubens ve Rembrandt\'ın da topladığı Flaman ressam kimdir?', 'Adriaen Brouwer', ['Adriaen van Ostade', 'Joos van Craesbeeck', 'Jan Steen'], 'Brouwer kısa yaşamında Haarlem ve Anvers\'te çalıştı. Abartılı yüz ifadeleri, onu bir tür duygu inceleyicisi yapmıştır.'),
  ('Rubens\'in tablolarındaki av hayvanlarını, köpekleri ve av natürmortlarını sıkça boyayan Anversli hayvan ressamı kimdir?', 'Frans Snyders', ['Paul de Vos', 'Jan Fyt', 'Adriaen van Utrecht'], 'Snyders, Rubens\'le birçok ortak eser üretti. Bol meyve, balık ve av hayvanlarıyla dolu pazar sahneleri Flaman Barok natürmortunun tipik örnekleridir.'),
  ('Natürmortlarındaki parlak kadeh ve kapların yüzeyine kendi küçük yansımasını gizleyen, 17. yüzyıl başının Anversli kadın natürmort ressamı kimdir?', 'Clara Peeters', ['Rachel Ruysch', 'Maria van Oosterwijck', 'Judith Leyster'], 'Peeters\'in yansıyan otoportreleri, kadın sanatçının varlığını ince bir yolla esere işler. Peynir, çörek ve balıklı masa düzenlemeleriyle tanınır.'),
  ('Rembrandt\'ın \'Belşazar\'ın Şöleni\' tablosunda kralı dehşete düşüren, duvarda beliren yazı nasıl yazılmıştır?', 'İbranice harflerle, dikey sütunlar hâlinde', ['Latince büyük harflerle, tek satırda', 'Yunanca harflerle, ters yönde', 'Hollandaca el yazısıyla, sağdan sola'], 'Rembrandt, yazının neden kimse tarafından okunamadığını açıklayan bir yoruma dayanarak harfleri dikey sütunlara dizdi. Bu bilgiyi Amsterdamlı haham Menasseh ben Israel\'den aldığı düşünülür.'),
  ('Rembrandt\'ın Amsterdam\'da yaklaşık altı ay yanında çalıştığı, İtalya\'da yetişmiş ve İncil konulu anlatı tablolarıyla tanınan tarih ressamı kimdir?', 'Pieter Lastman', ['Jacob van Swanenburgh', 'Hendrick Goltzius', 'Cornelis van Haarlem'], 'Rembrandt\'ın ilk hocası Leiden\'deki Jacob van Swanenburgh\'du. Lastman, ona canlı jestli ve renkli anlatı resmini öğretti.'),
  ('Amsterdam\'ın yeni belediye binası için yapılıp kısa süre sonra ressama geri gönderilen ve Rembrandt\'ın kesip küçülttüğü dev tablo hangisidir?', 'Claudius Civilis\'in Komplosu', ['Okçular Loncasının Şöleni', 'Diana\'nın Avı', 'Dr. Tulp\'un Anatomi Dersi'], 'Tablo Batavların Romalılara karşı ayaklanmasını anlatıyordu. Geriye kalan parça bugün Stockholm\'deki Ulusal Müze\'dedir.'),
  ('Rembrandt\'ın Leiden\'deki ilk öğrencisi olan ve son derece ince, pürüzsüz ayrıntılı küçük tablolarıyla Leiden \'ince ressamlar\' okulunu kuran ressam kimdir?', 'Gerrit Dou', ['Frans van Mieris', 'Jan Lievens', 'Gabriel Metsu'], 'Dou\'nun tabloları dönemin en pahalı eserleri arasındaydı. Fırça izinin görünmediği cilalı yüzeyleri, Rembrandt\'ın geç dönem kalın boyasının tam karşıtıdır.'),
  ('Haarlem\'de Pieter Claesz ve Willem Claesz Heda\'nın geliştirdiği, devrilmiş kadehler, yarım soyulmuş limonlar ve gümüş kapları sınırlı gri-kahverengi tonlarla gösteren natürmort türüne ne ad verilir?', 'Tek renkli ziyafet natürmortu', ['Gösterişli (pronk) natürmort', 'Çiçek vazosu natürmortu', 'Av hayvanı natürmortu'], 'Hollandaca \'monochrome banketje\' denen bu türde renk yerine ışık ve doku öne çıkar. Yarım kalmış yemek, geçicilik düşüncesine de gönderme yapar.'),
  ('Willem Kalf gibi ressamların Çin porseleni, Venedik camı, nautilus kabuklu kadehler ve Doğu halılarıyla zenginliği sergilediği gösterişli natürmort türünün Hollandaca adı nedir?', 'Pronkstilleven', ['Banketje', 'Bloemstuk', 'Tronie'], '\'Pronk\' gösteriş anlamına gelir. Bu tablolar Hollanda\'nın küresel ticaret ağıyla getirdiği lüks malları yansıtır.'),
  ('Lahey\'deki Mauritshuis\'te bulunan, bir çayırda duran genç bir boğayı neredeyse gerçek boyutunda gösteren 1647 tarihli ünlü hayvan tablosunun ressamı kimdir?', 'Paulus Potter', ['Aelbert Cuyp', 'Karel Dujardin', 'Philips Wouwerman'], 'Potter tabloyu yirmi iki yaşındayken yaptı. Bir hayvanın bu ölçekte tek başına konu edilmesi dönemi için olağandışıydı.'),
  ('Ufka doğru dümdüz uzanan, iki yanı sıska kavaklarla çevrili bir köy yolunu tek kaçış noktalı perspektifle gösteren \'Middelharnis Ağaçlı Yolu\' tablosunun ressamı kimdir?', 'Meindert Hobbema', ['Jacob van Ruisdael', 'Jan van Goyen', 'Philips Koninck'], 'Hobbema, Ruisdael\'in öğrencisiydi. 1689 tarihli bu tablo, onun en ünlü ve en çok kopyalanan eseridir.'),
  ('Gerard ter Borch\'un parlak saten elbiseli bir kadını oturan bir subay ve yaşlı bir kadınla gösteren tablosu, 18. yüzyılda \'Babanın Öğüdü\' diye adlandırılmıştı. Bugün sanat tarihçileri sahneyi genellikle nasıl yorumlar?', 'Bir genelevde geçen sessiz bir pazarlık sahnesi olarak', ['Kızına evlilik öğüdü veren bir babanın aile sahnesi olarak', 'Bir mahkemede ifade veren tanıkların sahnesi olarak', 'Ölüm döşeğindeki bir annenin vasiyet sahnesi olarak'], 'Adamın kaldırdığı elinde bir zamanlar boyalı bir sikke bulunduğu düşünülür. Eski başlık, Goethe\'nin de benimsediği ahlakçı bir yanlış okumadır.'),
  ('17. yüzyıl Hollanda çiçek natürmortlarında aynı vazoda farklı mevsimlerde açan lale, gül ve kar çiçeklerinin bir arada gösterilmesi neyi ortaya koyar?', 'Tablonun ayrı ayrı yapılmış çizimlerden kurgulanmış bir düzenleme olduğunu', ['Hollanda seralarında bütün çiçeklerin yıl boyu birlikte yetiştirilebildiğini', 'Ressamın çiçekleri yapay ipekten modellerden kopyaladığını', 'Bu türün yalnız kış aylarında üretilen bir zanaat olduğunu'], 'Ressamlar her çiçeği açtığı mevsimde inceleyip çizer, tabloda birleştirirdi. Böylece gerçekte görülmesi imkânsız, ideal bir buket oluşurdu.'),
  ('Lahey ressamlar loncasına kabul edilen, Düsseldorf\'ta saray ressamı olan ve çiçek natürmortları dönemin en yüksek fiyatlarına satılan Hollandalı kadın ressam kimdir?', 'Rachel Ruysch', ['Clara Peeters', 'Maria van Oosterwijck', 'Judith Leyster'], 'Babası ünlü bir anatomi ve botanik profesörüydü. Ruysch altmış yılı aşkın uzun bir kariyer boyunca çalıştı.'),
  ('Frans Hals\'ın seksen yaşlarındayken Haarlem\'deki bir yaşlılar yurdunun kadın yöneticilerini koyu giysiler ve sert yüz ifadeleriyle gösterdiği grup portresi hangisidir?', 'Huzurevi Kadın Yöneticileri', ['Aziz Yorgi Muhafızlarının Şöleni', 'Malle Babbe', 'Mutlu İçki Arkadaşı'], 'Hals\'ın son eserlerinden olan bu portre bugün Haarlem\'deki Frans Hals Müzesi\'ndedir. Hızlı ve kaba fırça vuruşları sonraki ressamlarca çok beğenilmiştir.'),
  ('2021\'de tamamlanan restorasyonda, arka duvarda üzeri sonradan boyanmış büyük bir Kupid tablosunun ortaya çıktığı Vermeer eseri hangisidir?', 'Açık Pencere Önünde Mektup Okuyan Kız', ['Mavi Giysili Mektup Okuyan Kadın', 'Mektup Yazan Hanım ve Hizmetçisi', 'Aşk Mektubu'], 'Laboratuvar incelemeleri, Kupid\'in Vermeer\'in ölümünden sonra başkası tarafından örtüldüğünü gösterdi. Eser Dresden\'dedir.'),
  ('Philippe de Champaigne\'in rahibe olan kızının Port-Royal manastırında mucizevi biçimde iyileşmesine şükran olarak yaptığı, iki rahibeyi sade bir hücrede gösteren tablo hangisidir?', '1662 Adak Tablosu', ['Kardinal Richelieu\'nün Üçlü Portresi', 'Son Akşam Yemeği', 'Ölü İsa'], 'Tablo, Jansenist çevrenin ağırbaşlı ve süssüz dindarlığını yansıtır. Kızı Catherine felçten kurtulmuş, ressam bu olayı bir şükran adağıyla kayda geçirmiştir.'),
  ('Charles Le Brun\'un Kraliyet Akademisi\'nde verdiği konferans ve çizimlerle ressamlara hangi konuda kurallar sunduğu bilinir?', 'Duyguların yüz ifadesinde gösterilmesi', ['Doğrusal perspektifin geometrik kuruluşu', 'Pigmentlerin hazırlanması ve saklanması', 'Freskte sıvanın katmanları'], 'Le Brun öfke, korku, hayranlık gibi tutkuları kaş, göz ve ağız biçimleriyle şemalaştırdı. Bu çizimler uzun süre akademik eğitimde örnek olarak kullanıldı.'),
  ('Ressamlara kompozisyon, çizim, renk ve ifade dallarında yirmi üzerinden puan veren \'Ressamlar Terazisi\' adlı listeyi 1708\'de yayımlayan Fransız kuramcı kimdir?', 'Roger de Piles', ['André Félibien', 'Charles Perrault', 'Giovan Pietro Bellori'], 'Listede Raffaello ve Rubens en yüksek puanları alırken Caravaggio\'nun ifade puanı sıfırdır. Liste, dönemin akademik değer ölçülerini somut biçimde gösterir.'),
  ('Nicolas Poussin\'in bir mektubunda müzikteki Dor ve Frig gibi kiplerden yola çıkarak geliştirdiği kurama göre ressam ne yapmalıdır?', 'Her konuya uygun bir duygu tonunu seçip bütün tabloyu ona göre kurmalıdır', ['Her tabloda bütün renkleri eşit oranda kullanmalıdır', 'Tabloları müzik eşliğinde izlenecek biçimde tasarlamalıdır', 'Antik konuları yalnızca tek renkle boyamalıdır'], 'Poussin\'e göre ciddi bir konu sert ve ağırbaşlı, neşeli bir konu canlı bir \'kip\' ister. Bu düşünce, resmin akılcı bir dil gibi kurulabileceği inancını yansıtır.'),
  ('Claude Lorrain\'in, sahte kopyaların çoğalması üzerine sattığı tabloların çizim kopyalarını topladığı ve sonradan gravürle yayımlanan defterin adı nedir?', 'Liber Veritatis', ['Codex Atlanticus', 'Liber Studiorum', 'Libro dei Disegni'], '\'Gerçeğin Kitabı\' anlamına gelen defter yaklaşık iki yüz çizim içerir. Bugün British Museum\'dadır.'),
  ('Madame du Barry\'nin Louveciennes\'deki köşkü için ısmarlayıp sonra geri çevirdiği ve bugün New York\'taki Frick Koleksiyonu\'nda bulunan Fragonard dizisi hangisidir?', 'Aşkın Gelişimi', ['Dört Mevsim', 'Kythera\'ya Yolculuk', 'Aşk Bahçesi'], 'Siparişin geri çevrilmesinin nedenlerinden biri zevkin Neoklasik sadeliğe kaymasıydı. Fragonard dizi yerine Joseph-Marie Vien\'in daha klasik panoları seçildi.'),
  ('François Boucher\'nin yüzüstü bir kanepeye uzanmış genç kızı gösteren ünlü tablosunun modeli olan ve sonradan XV. Louis\'nin gözdeleri arasına giren kişi kimdir?', 'Marie-Louise O\'Murphy', ['Madame de Pompadour', 'Madame du Barry', 'Marie Leszczyńska'], 'Tablonun bir kopyası kralın ilgisini çektiği anlatılır. Kızın İrlanda kökenli bir ailesi vardı ve Boucher\'nin birçok tablosunda model olarak görülür.'),
  ('Venedikli soyluların gündelik yaşamını küçük ve zarif tablolarla gösteren, 1751 karnavalında sergilenen Clara adlı gergedanı da resmeden ressam kimdir?', 'Pietro Longhi', ['Giandomenico Tiepolo', 'Rosalba Carriera', 'Michele Marieschi'], 'Longhi\'nin sahneleri, maskeli kalabalıklar ve salon eğlenceleriyle Goldoni\'nin komedilerine benzer bir toplumsal gözlem sunar.'),
  ('Giambattista Tiepolo\'nun oğlu olan ve aile villasının duvarlarını, commedia dell\'arte\'nin beyaz giysili Pulcinella figürlerini gösteren alaycı fresklerle süsleyen ressam kimdir?', 'Giandomenico Tiepolo', ['Lorenzo Tiepolo', 'Pietro Longhi', 'Sebastiano Ricci'], 'Babasının görkemli tavanlarından farklı olarak Giandomenico\'nun Pulcinellaları gündelik ve ironik bir dünyayı gösterir. Freskler bugün Venedik\'teki Ca\' Rezzonico\'dadır.'),
  ('Botticelli\'nin \'Primavera\'sının sağ yanında rüzgâr tanrısı Zephyros\'un yakaladığı peri Chloris\'in hemen yanında çiçekli giysiler içinde Flora durur. Bu iki kadın figürü birlikte neyi anlatır?', 'Ovidius\'a göre aynı kişinin dönüşümünün iki anını', ['Kıskançlıkla birbirine düşman olmuş iki kız kardeşi', 'Kışın ve baharın iki ayrı tanrıçasını', 'Bağışçı ailenin iki kızının portresini'], 'Ovidius\'un \'Fasti\'sinde Zephyros\'un sevdiği Chloris, çiçeklerin tanrıçası Flora\'ya dönüşür. Botticelli dönüşümü ağzından çiçekler dökülen Chloris ile gösterir.'),
  ('Holbein\'in \'Elçiler\' tablosunda iki adamın arasındaki rafın üst katında gök küreleri ve zaman ölçerler, alt katında ise bir teli kopuk lavta ve açık bir ilahi kitabı yer alır. Bu alt kattaki nesneler en çok neyi ima eder?', 'Reform dönemindeki dinsel ve siyasal uyumsuzluğu', ['İki elçinin müzisyen olarak çalıştığını', 'Ressamın lavta çalmayı öğrendiğini', 'İngiltere\'nin deniz ticaretindeki ve keşiflerdeki zaferini'], 'Kopuk tel uyumun bozulmasını, Luther\'in çevirisinden bir ilahi ise Hristiyanlık içindeki bölünmeyi akla getirir. Tablo 1533\'te, VIII. Henry\'nin Roma\'dan kopuşu sırasında yapılmıştır.'),
  ('Pieter Aertsen\'in 1551 tarihli \'Kasap Tezgâhı\' tablosunda ön planı et ve sucuk yığınları doldururken, Mısır\'a Kaçış sahnesi arka planda küçücük bir ayrıntı olarak kalır. Bu düzen genellikle nasıl yorumlanır?', 'Dünyevi bolluğun öne çıkıp kutsal olayın geri itildiği ahlaki bir tersine çevirme', ['Ressamın dinsel konuyu bilmeden yanlışlıkla eklediği bir ayrıntı', 'Kasapların loncası için yapılmış bir reklam afişi', 'Arka plandaki sahnenin sonradan başka biri tarafından boyanması'], 'Ters çevrilmiş kompozisyon, izleyiciyi maddi zevkler ile ruhsal değerler arasında seçime çağırır. Bu tür tablolar bağımsız natürmortun doğuşunda önemli bir aşamadır.'),
  ('Roma\'daki Dört Irmak Çeşmesi\'nde elini kaldıran bir ırmak figürünün, Borromini\'nin karşıdaki kilisesinin çökeceğinden korktuğu için gözlerini kapattığı anlatılır. Bu söylence neden tarihsel olarak çürüktür?', 'Çeşme, Borromini\'nin kilise cephesine başlamadan önce tamamlanmıştır', ['Borromini\'nin hiçbir zaman Roma\'da çalışmamış olması', 'Çeşmede insan figürü bulunmaması', 'Kilisenin çeşmeden iki yüzyıl önce yıkılmış olması'], 'Çeşme 1651\'de bitti; Borromini\'nin Sant\'Agnese cephesi üzerindeki çalışması ise 1653\'te başladı. Söylence, iki ustanın ünlü rekabetinden doğmuştur.'),
];
